    "id": "377460",
    "name": "Ariana Richards",
    "bio": "Ariana Richards is an American actress and artist best known for her role as Lex Murphy in Steven Spielberg's Jurassic Park, a performance that introduced her to international audiences and became one of the film's most memorable portrayals. She reprised the role in The Lost World: Jurassic Park, further cementing her association with the iconic franchise.\n\nRichards began acting as a child, appearing in numerous film and television projects throughout the 1990s. Her early screen credits include Tremors, Prancer, Angus, and television series such as The Golden Girls, Empty Nest, Boy Meets World, and Across the Tracks. Her work during this period demonstrated a natural talent for both drama and family-oriented storytelling.\n\nIn addition to acting, Richards is an accomplished fine artist. After studying at Skidmore College and later refining her training in Florence, Italy, she established a successful career as a painter, specializing in classical and impressionistic portraiture. Her artwork has been exhibited professionally and earned awards within the fine arts community.",
    "knownFor": "Jurassic Park",
