    "id": "377625",
    "name": "Bill Barretta",
    "bio": "Bill Barretta began performing with The Jim Henson Company in 1991 landing the lead character of Earl Sinclair on the ABC hit television series Dinosaurs and would soon become one of the leading Core Muppet performers.\n\nHis characters include Pepe the King Prawn, Johnny Fiama, Big Mean Carl and Bobo the Bear, to name a few. In addition, Barretta is honored to carry on several of Jim Henson's beloved creations: Rowlf the Dog, The Swedish Chef and Dr. Teeth.\n\nOver the last thirty years Barretta has also directed, executive produced, written and coordinated for many Muppet projects to name a few; Muppet Treasure Island, Muppets Tonight, Muppets From Space, The Muppets 2011 feature, The Muppets 2015 ABC series and the 2021 Disney+ Halloween special Muppets Haunted Mansion – In addition; countless Appearances, talk shows, commercials, social media content and live shows including Jimmy Fallon, Jimmy Kimmel, James Corden, Long John, Silvers, Pizza Hut, Subway, Lipton, Toyota, PAM, Adidas, Geico, MuppetFest’s Muppet Show Live, The Muppets Take the Hollywood Bowl, The Muppets Take the O2. And most recently for Disney+, the Co-creator, writer, performer, and executive producer of The Muppets Mayhem.\n\n...Oh, and he’s a nice Italian boy.\n\nBill also has a Vodcast with his brother Gene. It's called The Barretta Brothers. It's all things Muppets and Art. They've had many great Muppet related guests since the show began during the pandemic. See links below for more information about the Vodcast!",
