    "id": "379750",
    "name": "Bill Sienkiewicz",
    "bio": "Bill Sienkiewicz (pronounced sin-KEV-ich) is a multi-Eisner Award-winning and Emmy Award-nominated artist known for revamping the style of comic and graphic novel illustration—a feat earning him an international reputation across media industries, as well as entrée into the Eisner Hall of Fame. He is most noted for Marvel's Elektra: Assassin, Moon Knight, and New Mutants—inspiring FX’s Legion and Disney’s New Mutants—and his acclaimed graphic novel Stray Toasters. He earned two Emmy nominations for his work on the animated series Where in the World Is Carmen Sandiego? Sienkiewicz has also contributed on-set and promotional artwork for Spider-Man: Into the Spider-Verse and Spider-Man: Across the Spider-Verse, The Batman, Dune: Part One, Dune: Part Two, Moon Knight series, 2018 Halloween remake, Logan, The Grinch, The Green Mile, and Unforgiven. His work has graced numerous album and book covers, U.S. Olympic campaigns, and museums and galleries across the US, Canada, Europe, and Brazil. In 2025, his work, Space Batman, spent a month aboard the International Space Station. Bill is the subject of the highly anticipated documentary, That Polish Guy, due next year.",
    "knownFor": "Multi-Eisner Award-winning and Emmy Award-nominated artist; Marvel's Elektra: Assassin, Moon Knight, and New Mutants",
