    "id": "380144",
    "name": "Charlie Cox",
    "bio": "Charlie Cox is a British actor best known for his portrayal of Matt Murdock/Daredevil in the Netflix series \"Daredevil\" (2015-2018) and within the Marvel Cinematic Universe. His captivating performance as the blind lawyer-turned-superhero garnered critical acclaim and a devoted fanbase, highlighting his ability to bring depth and nuance to a complex character.\n\nCox's acting career spans both film and television, with notable roles in projects like \"Stardust\" (2007), where he played the lead role of Tristan Thorn, and \"The Theory of Everything\" (2014), where he showcased his dramatic talents in a supporting role.\n\nIn addition to his screen work, Cox has also been involved in theater productions, further demonstrating his range as an actor. His contributions to both popular and critically acclaimed projects have solidified his status as a prominent figure in the entertainment industry.",
