    "id": "379466",
    "name": "Chris Claremont",
    "bio": "Chris Claremont writes both comics and prose. His initial unbroken 17-year run on Marvel Comics’ “Uncanny X-Men” is the stuff of industry legend. Chris has written other seminal characters such as Batman and Superman, and The Fantastic Four. He is especially proud of his creator-owned work, with includes The Black Dragon and Marada, the She-Wolf (art by John Bolton). He is the author of nine novels, with more on the way.",
