    "id": "380014",
    "name": "Grant Gustin",
    "bio": "Grant Gustin is an actor best known for playing Barry Allen / The Flash across all nine seasons of The CW's The Flash (2014–2023), appearing in 184 episodes and making him the longest-running live-action incarnation of the character. He also reprised the role extensively across the Arrowverse, appearing in Arrow, Supergirl, Legends of Tomorrow, and Batwoman crossovers.\n\nPrior to The Flash, Gustin had a recurring role as Sebastian Smythe in Glee (2011–2013). Outside the Arrowverse, he starred in the Netflix film Rescued by Ruby (2022) and Puppy Love (2023).",
