    "id": "377579",
    "name": "Jacob Phillips",
    "bio": "Jacob Phillips is an Eisner Nominated comic artist and colourist from the UK. He has worked on a number of Creator Owned projects such as The Peril of the Brutal Dark That Texas Blood and The Enfield Gang Massacre with writer Chris Condon Newburn with Chip Zdarsky & recent fan favorite project Everything Dead & Dying with writer Tate Brombal. He also was the artist of the graphic novel of Francis Ford Coppola’s MEGALOPOLIS.\n\n@thatjacobphillips.bsky.social",
    "knownFor": "Everything Dead & Dying, The Peril of the Brutal Dark, That Texas Blood - The Enfield Gang Massacre",
