    "id": "377455",
    "name": "Jennifer English",
    "bio": "Jennifer English is a voice actress known for her contributions to various video games and television productions. She has lent her talents to notable projects such as \"Baldur's Gate III\" (2023), where she provided voices for characters in the expansive fantasy world, and \"Elden Ring\" (2022), a highly anticipated action role-playing game.\n\nAdditionally, Jennifer English has appeared in the true crime television series \"The Killer Beside Me\" (2018), showcasing her acting skills in a different genre. She is also an advocate for diversity and inclusivity in gaming, striving to create spaces where all gamers feel welcome and valued.",
