    "id": "377608",
    "name": "Jody Houser",
    "bio": "Jody Houser is an acclaimed comic book writer known for her work across comics, television, film, and gaming franchises. She has written titles for Marvel, DC, Dark Horse, IDW, and Titan Comics, including Star Wars, Stranger Things, Doctor Who, Critical Role, Harley Quinn & Poison Ivy, and Spider-Man. Renowned for her skill in adapting beloved properties while crafting compelling original stories, Houser has become one of the most versatile and in-demand writers working in comics today.",
