    "name": "John Cusack",
    "bio": "John Cusack is an actor, writer, producer, and director whose career and political activism spans more than four decades. His first book, Things That Can and Cannot Be Said, co-authored with Arundhati Roy, was published worldwide. He has appeared in more than 90 films and dozens of documentaries. His second collaboration with Ignacio Noé, The Chymicle Wedding, is already underway. Cusack resides in Chicago.",
