    "id": "378912",
    "name": "John Scalzi",
    "bio": "JOHN SCALZI is one of the most popular science fiction authors of his generation. His debut, Old Man's War, won him the John W. Campbell Award for Best New Writer. His New York Times bestsellers include The Last Colony, Fuzzy Nation, Redshirts (which won the Hugo Award for Best Novel), The Last Emperox, The Kaiju Preservation Society, and Starter Villain. Material from his blog, Whatever, has earned him two other Hugo Awards. He lives in Ohio with his wife and daughter.\n\nFollow me on BlueSky",
