    "id": "377606",
    "name": "Kami Garcia",
    "bio": "Kami Garcia a #1 New York Times USA Today and international bestselling author and comic book writer. As an award-winning young adult author of 20 novels and graphic novels she has been published in 51 countries and 38 languages and her books have sold more than 10 million copies worldwide. Kami's best known works include Beautiful Creatures which was adapted as a feature film by Warner Brothers and Alcon Entertainment the Bram Stoker nominated Legion Series and her Teen Titans graphic novel series for DC which has sold over half a million copies. Kami is also a cofounder of the Kid Lit book festival YALLFest. Learn more about Kami at kamigarcia.com and follow her on Instagram @kamigarcia.",
    "knownFor": "Teen Titans, Beautiful Creatures",
