    "id": "380145",
    "name": "Krysten Ritter",
    "bio": "Krysten Ritter is an American actress, musician, and author. She is best known for playing Jessica Jones in the Marvel series Jessica Jones and The Defenders. She also starred in the ABC comedy Don't Trust the B---- in Apartment 23 and appeared in Breaking Bad as Jane Margolis.\n\nHer film credits include Confessions of a Shopaholic, Big Eyes, and Veronica Mars. Beyond acting, Ritter has worked as a musician with her band Ex Vivian and authored a novel, Bonfire. Her career demonstrates range across television, film, music, and writing.",
