    "id": "377561",
    "name": "Lee Bermejo",
    "bio": "Lee Bermejo's career began in 1997 as an intern at WildStorm. He is self-taught with little formal art training. His first credited comics work appeared in Gen 13 #43 (Sept. 1999). His notable works include \"What's So Funny About Truth Justice & the American Way?\" story in Action Comics #775 the Lex Luthor: Man of Steel limited series in 2005 the Joker graphic novel the Batman: Noël graphic novel Before Watchmen: Rorschach limited series Suiciders We Are Robin Batman Damned and Detective Comics. He is currently working on Amazing Spider-Man creating Amazing Visions covers.",
