    "id": "377609",
    "name": "Melissa Fumero",
    "bio": "Melissa Fumero is an actress best known for playing Amy Santiago across all eight seasons of NBC's Brooklyn Nine-Nine (2013–2021), the hyper-organized, overachieving detective whose arc from rule-follower to precinct sergeant made her one of the show's most compelling characters. \n\nBefore Brooklyn Nine-Nine, Fumero had a long-running role as Adriana Cramer on the daytime soap One Life to Live (1998–2011). More recently she led Grosse Pointe Garden Society (2025) and had a recurring role in Based on a True Story (2024). She also reunited with Brooklyn Nine-Nine co-star Andy Samberg, voicing Bella across 16 episodes of his animated series Digman! (2023–2025). Additional credits include Blockbuster (2022) and M.O.D.O.K. (2021).",
