    "id": "377589",
    "name": "Mike Liscio",
    "bio": "Mike Liscio is a voice artist, actor, comedian, and writer best known for his roles on Pokèmon: XYZ, Sun & Moon, and Journeys including Clemont, Ilima, Magikarp, Inkay, Lycenroc, Litleo, Trumbeak, Komala, & more, as well as his roles on Yu-Gi-Oh: Arc V, VRAINS, and GO RUSH including Yuya, Yuto, Yugo, Yuri, ZARC, Yusho, and AI, and Teru Kawai! He’s also recorded a number of video games (Super Smash Bros: Ultimate, Contra: Rogue Corps, Yu-Gi-Oh Duel Links, Cross Duels, Lego Legacy), Podcasts (Murder in HR) commercials, apps, and more! He is also a comedian and influencer with tons of viral content across social media (IG/TT: @mikeylish). Mike has been on Broadway stages (Avenue Q), the silver\nscreen (Coup!, Law & Order), award winning web-series (Sorry Ari), and has written and produced tons of sketch comedy.",
