    "id": "377612",
    "name": "Mirka Andolfo",
    "bio": "Mirka Andolfo is an internationally acclaimed Italian writer and artist known for her distinctive blend of fantasy, romance, and humor. She is the creator of bestselling series including Sweet Paprika, Mercy, and Unnatural, whose work has been translated into multiple languages and earned a worldwide following. In addition to her creator-owned successes, Andolfo has worked with DC Comics, Marvel, Dynamite, and Image Comics on titles featuring Harley Quinn, Wonder Woman, Catwoman, and other iconic characters. Her unique artistic style and storytelling have made her one of the most recognizable creators in modern comics.",
