    "id": "377551",
    "name": "Nick Dragotta",
    "bio": "Nick is the artist/co-creator of ABSOLUTE BATMAN. His first solo creator-owned work is GHOST CAGE. Previously he was the artist/co-creator (with writer Jonathan Hickman) on the acclaimed series EAST OF WEST. He was also a longtime Marvel artist on such titles as FF (also with Hickman) VENGEANCE X-STATIX and more. Most notably he co-created the character America Chavez. We are proud to represent his work here!",
