    "id": "379267",
    "name": "R.L. Stine",
    "bio": "R.L. Stine is one of the best-selling children's authors in history. His Goosebumps and Fear Street series have sold more than 400 million copies around the world and have been translated into 32 languages. He has had several TV series based on his work, and two feature films, The Goosebumps Movie (2015) and Goosebumps 2: Hunted Halloween (2018), starred Jack Black as R.L. Stine himself. Just Beyond is his first-ever series of graphic novels. Bob lives in New York City with his wife Jane, an editor and publisher.",
    "knownFor": "Goosebumps",
