    "id": "379363",
    "name": "Raina Telgemeier",
    "bio": "Raina Telgemeier is the #1 New York Times bestselling, multiple Eisner Award–winning creator of Smile, Sisters, and Guts, which are all graphic memoirs based on her childhood. She is also the creator of Drama and Ghosts, an adapter and illustrator for five Baby-sitters Club graphic novels, and, with Scott McCloud, the cocreator of The Cartoonists Club. Facing Feelings: Inside the World of Raina Telgemeier is based on an exhibition that was held at The Ohio State University’s Billy Ireland Cartoon Library & Museum.",
