    "id": "377604",
    "name": "Ryan Ottley",
    "bio": "Ryan Ottley is an award-winning comic book artist and writer best known for his long-running work on Invincible, the acclaimed creator-owned superhero series co-created by Robert Kirkman. Celebrated for his dynamic action sequences and expressive storytelling, Ottley helped define the look of Invincible across more than a decade of issues. He later brought his energetic style to Marvel Comics, serving as the artist on The Amazing Spider-Man and working on titles including Hulk and Venom. Ottley remains one of the most popular and influential superhero artists in comics today.",
    "knownFor": "Invincible, The Amazing Spider-Man",
