    "id": "378746",
    "name": "Stephanie Beatriz",
    "bio": "Stephanie Beatriz is an actress and voice actress best known for playing Rosa Diaz across all eight seasons of NBC's Brooklyn Nine-Nine (2013–2021), the deadpan, intensely private detective whose coming out storyline became one of the show's most celebrated arcs.\n\nIn animation, Beatriz voiced Mirabel in Disney's Encanto (2021) and reprised the role across multiple specials and the Disney Dreamlight Valley video game. She also voices Vaggie in Hazbin Hotel (2024–2025), including the live Broadway special, and has voiced characters in The Lego Movie 2: The Second Part (2019), Twisted Metal (2023–2025), The Legend of Vox Machina (2022–2026), Big Mouth (2023–2025), and Hit-Monkey (2024). Additional film credits include In the Heights (2021) and Short Term 12 (2013). Most recently she leads A Man on the Inside (2024–2025) opposite Ted Danson and appeared in Zootopia 2 (2025).",
    "knownFor": "Brooklyn 99, Encanto, Hazbin Hotel, Twisted Metal",
