    "id": "377595",
    "name": "Tom King",
    "bio": "Tom King is an Eisner Award–winning writer known for his emotionally complex and character-driven approach to superhero storytelling. A former CIA counterterrorism officer, King has become one of comics' most celebrated writers through acclaimed runs on Batman, Mister Miracle, Supergirl: Woman of Tomorrow, The Human Target, Vision, and Wonder Woman. His work has earned widespread critical acclaim for blending psychological depth with epic storytelling, making him one of the defining comic writers of the modern era.",
