    "id": "378482",
    "name": "Tony Daniel",
    "bio": "Comics 30 years veteran who broke on the scene in the 90s at Marvel Comics working on X-Force, then moved to Image for Spawn:Blood Feud with Alan Moore before launching his own set of creator owned titles, The Tenth, Adrenalynn, F5 and Silke. Returned to mainstream comics to work on Teen Titans with Geoff Johns before moving to Batman with Grant Morrison and then taking over the writing and art duties for Batman: Battle for the Cowl as well as the main title Batman. Other notable works include Deathstroke, Nocterra and self published Edenwood before once again returning to the mainstream in a full circle event that found him on X-Men in 2025-2026. Now working on the much anticipated launch of Maximum X-Men with writer Christopher Yost debuting December 2026.",
