    "id": "379300",
    "name": "V.E. Schwab",
    "bio": "VICTORIA “V. E.” SCHWAB is the #1 New York Times bestselling author of more than twenty books. Schwab's series and standalone titles for readers of all ages have made her a major literary figure, whose notable works include the Villains series, the Shades of Magic universe, The Invisible Life of Addie LaRue, and Bury Our Bones in the Midnight Soil. When not haunting Paris streets or writing in the corner of her favorite coffee shop, she lives in Edinburgh, Scotland.",
