    "id": "378771",
    "name": "Veronica Roth",
    "bio": "VERONICA ROTH is the #1 New York Times best-selling author of numerous titles including When Among Crows, Chosen Ones, the Divergent series, the Carve the Mark duology, Seek the Traitor’s Son and the recently released, The Sixth Faction. Veronica lives with her husband and their dog in Chicago, a city that she lovingly features (and frequently destroys) in many of her novels.",
