    "name": "Yo Mutso",
    "altName": "Peach Momoko",
    "bio": "Peach Momoko is an illustrator from Japan known for watercolor paintings. She wrote and illustrated Marvel's Demon Days, Ultimate X-Men, and Star Wars. Creator of Marvel character Maystorm. 2021 and 2024 Eisner Best Cover artist. Other than comics, she has worked on TOOL, Linkin Park, Babymetal, MTG, One Piece TCG, and many more.",
