    "id": "381043",
    "name": "Adam McArthur",
    "bio": "Adam McArthur is best known as the voice of main protagonist, Yuji Itadori, in the multi-award winning anime , Jujutsu Kaisen. His voice can be heard in numerous anime including Demon Slayer, Kaiju No. 8, Tokyo Revengers, My Hero Academia, Beyblade X, Bingo Stray Dogs, and more. He was also the voice of Marco Diaz on the hit Disney series, Star vs. The Forces of Evil, and has worked on tv shows and video games, including Homestuck, Big City Greens, Star Wars: The Clone Wars, Date Everything, WWE 2K24-26, Fire Emblem Shadows, Ghostwire Tokyo, and Far Cry 5. Adam can also be heard as the official voice of Disney XD television channel.",
