    "id": "379409",
    "name": "Al Milgrom",
    "bio": "Al Milgrom is an award winning comic book Professional. He started in the business in 1972 and has written pencilled inked and edited comics for a number of publishers. Primarily for Marvel Comics but also for DC Archie and a host of smaller publishers. He is known for inking Jim Starlin and has worked on characters such as Captain Marvel The Guardians of the Galaxy Master of Kung Fu Spider-Man The Avengers West Coast Avengers and the Kitty Pryde & Wolverine limited series. He inked X-Factor for over 8 years and is known for creating The Spot and co-creating Firestorm. As an editor he created Marvel Fanfare which paved the way for the modern format of current comics. He is exhausted!",
    "knownFor": "Spectacular Spider-man 99, Amazing Spiderman 194, Firestorm #1",
