    "id": "379309",
    "name": "Alex Singer",
    "bio": "Alex T. Singer lives in coastal Connecticut with her wife, daughter, and more sci-fi fantasy novels than she can count. She is the author of the graphic novel Mirrorverse: Belle. Her short stories have appeared in Luna Station Quarterly, Apparition Literary Magazine, Clarkesworld, and PseudoPod. Her short story, “Nothing but the Gods On Their Backs” was a finalist in the 2024 WSFA Small Press Award category for short fiction. For more of her work, visit LittleFoolery.com.",
