    "id": "380648",
    "name": "Alfredo Cardona",
    "bio": "Alfredo Cardona (acecore2kx) is an illustrator and comic artist recognized for his dynamic character work drawing inspiration from anime fighting games and classic American comics. His style blends expressive anatomy bold posing and high-energy storytelling across both traditional and digital media. He also has a background in concept art having collaborated with major studios such as Disney LATAM and Sony Entertainment. In addition he has contributed variant covers for titles including Thundercats Conan MotU and more.",
