    "id": "379265",
    "name": "Ally North",
    "bio": "Ally North (she/her) is a queer writer who has been writing fiction her entire life. During the pandemic, she began writing sapphic romance out of pure chaotic boredom and discovered an untried knack for the genre. She lives in America, but occasionally she lives in England. When she isn’t writing, Ally can be found cooking with obscene amounts of garlic, traveling someplace new, rescuing animals, and feeding Jean-Claude, the wild possum who lives under her shed.",
    "knownFor": "Bloom Town: Genesis",
