    "id": "379006",
    "name": "André Santana",
    "bio": "André Santana is a voice actor on a journey to tell great stories. He's the award-winning narrator behind audiobooks like Bury Your Gays by Chuck Tingle, The Sunbearer Trials by Aiden Thomas, and The Secret Dinner by Raphael Montes. He’s brought stories to life from authors like Brandon Sanderson, Marie Lu, Bryan Washington, Tegan & Sara Quin, Roberto Bolaño, and many more. With over 250 titles recorded between his name and his pseudonym Victor Quixabas, he brings a human touch to every title he works on.",
    "knownFor": "The Secret Dinner, Red City, Mutiny",
