    "id": "378774",
    "name": "Chelsea Abdullah",
    "bio": "Chelsea Abdullah is the award-winning author of The Sandsea Trilogy. An American-Kuwaiti writer born and raised in Kuwait, she grew up listening to stories about mysterious desert creatures and wily (only sometimes likable) heroes. When not immersed in her own fictional worlds, she spends her free time playing video games, doodling characters, and hoarding books she doesn’t have the shelf space for.",
