    "id": "379266",
    "name": "Chuck Wendig",
    "bio": "Chuck Wendig is the New York Times bestselling author of Wanderers, The Book of Accidents, Wayward, and more than two dozen other books for adults and young adults. A finalist for the Astounding Award and an alumnus of the Sundance Screenwriters Lab, he has also written comics, games, and for film and television. He’s known for his popular blog, terribleminds, and books about writing such as Damn Fine Story. He lives in Bucks County, Pennsylvania, with his family.",
