    "name": "Cindy Pham",
    "bio": "Cindy Pham is a queer Vietnamese-American author of instant #1 New York Times, USA Today, and Indie Bestseller THE SECRET WORLD OF BRIAR ROSE. Based in New York City, she works as a full-time designer while moonlighting as a fiction writer and content creator. Her YouTube channel, Read With Cindy, has amassed over half a million subscribers and focuses on books, movie reactions, and candid commentary. You can follow her across socials on @readwithcindy.",
