    "id": "377545",
    "name": "Cliff Chiang",
    "bio": "Cliff Chiang’s artwork has been hailed for its “fluid and confident storytelling” and “sweeping linework and nuanced style.” Graduating from Harvard University with a joint degree in English Literature and Visual Arts he worked in editorial at Disney Adventures Magazine and Vertigo/DC Comics before making the leap into freelance illustration. Clients include DC Comics GQ Magazine Lucasfilm Warner Animation Dark Horse Comics Dynamic Forces Entertainment and the ACLU.",
