    "id": "379541",
    "name": "Clémence Michallon",
    "bio": "CLÉMENCE MICHALLON was born and raised near Paris. She studied journalism at City University of London, received a master's in Journalism from Columbia University, and has written for The Independent since 2018. Her debut thriller, The Quiet Tenant, was published in 2023. She moved to New York City in 2014 and recently became a US citizen. She now divides her time between New York City and Tarrytown, NY.",
    "knownFor": "Our Last Resort, The Quiet Tenant",
