    "id": "380664",
    "name": "Cody Ziglar",
    "bio": "Cody Ziglar is an Emmy nominated LA based writer director and producer. He's best known for Futurama Rick & Morty She-Hulk: Attorney at Law Robot chicken and Craig of the Creek. His comic-book work includes Miles Morales: Spider-Man Deadpool and Spider-Punk for Marvel Comics. Cody's a graduate of the Savannah College of Art & Design Film & Television MFA program and has produced podcasts for Earwolf iHeartRadio and UCB Comedy. And directed videos featured on Funny or Die Cracked WhoHaha and more.",
