    "id": "381246",
    "name": "Colleen Clinkenbeard",
    "bio": "Colleen Clinkenbeard is a actress, writer, and director known for her extensive works in anime. She provides voices for many memorable characters such as Monkey D. Luffy in ONE PIECE, Riza Hawkeye in FULLMETAL ALCHEMIST, Erza Scarlet in FAIRY TAIL, Momo Yaoyorozu in MY HERO ACADEMIA, and most recently as Jinn the sixth season of RWBY. \n\nIn video games, Colleen has provided the voice of Lilith from BORDERLANDS 2 and Young Gohan in DRAGON BALL Z: FIGHTER.",
