    "id": "379761",
    "name": "Dave Roman",
    "bio": "Dave Roman is the author/illustrator of several graphic novel series, including Unicorn Boy and Astronaut Academy. He’s worked as a writer on Teen Boat! Race for Boatlantis (with John Patrick Green) and as an illustrator for Goosebumps Graphix: Slappy’s Tales of Horror. Dave teaches at the School of Visual Arts and worked as an editor for InvestiGators by John Patrick Green, First Second’s Science Comics, and Nickelodeon Magazine. Dave draws a webcomic called Pup & Duck, lives in New York City, and is always on the lookout for the perfect waffle.",
