    "id": "381045",
    "name": "David Matranga",
    "bio": "David Matranga is an American voice actor who works primarily for English dubbed anime for Funimation and Sentai Filmworks. Matranga is best known as the voice of Shoto Todoroki from My Hero Academia, Hideki Hinata from Angel Beats, Genjo Sanzo from Saiyuki, Orphen from Sorcerous Stabber Orphen, Bertholdt Hoover from the popular Attack on Titan series, Tomoya Okazaki from the Clannad series,Takumi Usui from Maid Sama, Ghost from the Halo Legends movie, Briareos from the Appleseed series, Yu Himura from the EF series, and God Serena from Fairy Tail.",
    "knownFor": "My Hero Academia - Shoto Todoroki Attack on Titan - Bertholdt Hoover One Piece - Charlotte Cracker Trigun Stampede - Nicholas D. Wolfwood Street Fighter 6 - Ken Masters Fire Emblem Engage - Zelkov",
