    "id": "378418",
    "name": "Dr. Katherine Cartwright",
    "bio": "Dr. Katherine Cartwright is the Senior Historical Researcher at American Girl, where she leads research for character development and brand history storytelling. In her time at American Girl, she has developed several characters, including the 1990s historical twins Isabel and Nicki and Girl of the Years Kavi (kuh-VEE), Lila, Summer, Raquel, and Daisy. She also led research for the brand’s 40th anniversary book, The Making of American Girl, and its first adult novel, Samantha: The Next Chapter.",
