    "id": "379310",
    "name": "Eric LaRocca",
    "bio": "Eric LaRocca (he/they) is a three-time Bram Stoker Award finalist and Splatterpunk Award winner. He was named by Esquire as one of the “Writers Shaping Horror’s Next Golden Age” and praised by Locus as “one of the strongest and most unique voices in contemporary horror fiction.” LaRocca’s notable works include Things Have Gotten Worse Since We Last Spoke, Everything the Darkness Eats, and At Dark, I Become Loathsome. He currently resides in Boston, Massachusetts, with his partner.",
