    "id": "378839",
    "name": "Fancy Feast",
    "bio": "Fancy Feast (Miss Coney Island 2016) is a Brooklyn-based burlesque performer and writer. Her debut essay collection, Naked: On Sex, Work, and Other Burlesques was published in October 2023 by Algonquin Books. Her work has been featured in Vogue Magazine, The Huffington Post, and The Washington Post, and she performs at venues including The Metropolitan Opera, The Whitney, and in dirty little backrooms all over America.",
