    "id": "378466",
    "name": "Francine Delgado",
    "altName": "Fran Delgado",
    "bio": "Francine Delgado is a Costa Rican–Canadian comic artist cover artist and character designer. She was a 2025 Ringo Award Nominee for Best Cover Artist and contributed to the Clampett Humanitarian Award–winning anthology LA Strong (2025). Her credits include Teenage Mutant Ninja Turtles and The Addams Family (IDW) Gatchaman Speed Racer and Flash Gordon (Mad Cave) and Legendary: Black Widow (Marvel Upper Deck). Influenced by manga European comics and fashion design Francine creates striking covers and sequential art for publishers such as Marvel IDW and Mad Cave blending style and storytelling to captivate readers.",
    "knownFor": "TMNT, Gatchaman, The Addams Family",
