    "bio": "Gale Galligan is the New York Times bestselling, award-winning creator of Freestyle, Fresh Start, and four Baby-sitters Club graphic novel adaptations. When they aren't making comics, Gale enjoys knitting, drumming, and spending time with their family and pets in Pearl River, New York. Gale is a founding member of the Comics Advocacy Group, a 501(c)3 nonprofit that is dedicated to making careers in comics more accessible and sustainable.",
