    "id": "379306",
    "name": "Gareth Hinds",
    "bio": "Gareth Hinds is the creator of critically-acclaimed graphic novels based on literary classics, including Beowulf, The Odyssey, The Iliad, Romeo & Juliet, Macbeth, and POE: Stories and Poems. Gareth is a recipient of the Boston Public Library’s “Literary Lights for Children” award. His books can be found in bookstores and English classrooms across the country, and his illustrations have appeared in such diverse venues as the Society of Illustrators, the New York Historical Society, and over a dozen published video games.",
