    "id": "378470",
    "name": "Geof Darrow",
    "bio": "Born and raised in Iowa moved to Chicago for art school. Worked in multi media agency until I moved to Los Angeles and worked as a character designer at Hana Barbera until I moved to Paris France to begin my career in comics. Moved back to Los Angels and began my career in American comics and later a concept designer in motion pictures but still prefer drawing his own comics most notably The Shaolin Cowboy",
