    "id": "381130",
    "name": "Grady Hendrix",
    "bio": "Grady Hendrix is a New York Times bestselling novelist and screenwriter who owns too many paperbacks and not enough shelves. He's the author of Witchcraft for Wayward Girls, How to Sell a Haunted House, The Southern Book Club's Guide to Slaying Vampires, and many more, including Paperbacks from Hell, a history of the horror paperback boom of the seventies and eighties that won the Bram Stoker Award for Superior Achievement in Nonfiction. His books have sold over three million copies and have been translated into more than twenty languages. You can find more useless facts about him at www.gradyhendrix.com",
