    "id": "379015",
    "name": "Hanna Harp",
    "bio": "Hanna Harp is an artist and voice narrator with a deep love for dark, paranormal romance. She began writing her debut novel, Haunting the Hunter, while navigating the lifelong realities of dissociation, using storytelling as a way to stay connected when the world feels unreal. Hanna lives in the Midwest with her partner and two daughters, learning to accept her mind as it is and still reach for her own version of happily ever after.",
