    "id": "379014",
    "name": "I.V. Ophelia",
    "bio": "USA TODAY bestselling author I.V. Ophelia is known for her gothic vampire series The Poisoner. Born in small-town New England, she now haunts the streets of New York City, writing the most unhinged tales she can conjure. When not crafting gothic romance, she works as a full-time artist, hoards 19th-century gowns and antique furniture, dotes on her menagerie of pets, and plots her next literary transgression.",
