    "id": "381044",
    "name": "Ian Sinclair",
    "bio": "Ian Sinclair is an actor, director, and voice actor with nearly two decades of experience in anime and video games. His best-known roles include Whis in Dragon Ball Super, Bokuto in Haikyuu!!, Dandy in Space Dandy, Mezo Shoji in My Hero Academia, Brook in One Piece, Kureno Soma in Fruits Basket, Magna Swing in Black Clover, Tsukasa in Dr. Stone, Viktor Licht in Fire Force, Azami Nakiri in Food Wars!, Souei in That Time I Got Reincarnated as a Slime, Bardroy in Black Butler, the Narrator in Kaguya-sama: Love Is War, Sherlock Holmes in Case File nº221: Kabukicho, and Saichi “The Immortal” Sugimoto in Golden Kamuy. He has also voiced characters in Assassination Classroom, Bob Epic Team, and Borderlands 3.",
