    "id": "380703",
    "name": "Isaac Goodhart",
    "bio": "Isaac Goodhart got his start in comics with Top Cow Productions and illustrated twenty-six issues of Postal. He later went to DC Comics and illustrated Under the Moon: A Catwoman Tale Victor and Nora: A Gotham Love Story and Constantine: Distorted Illusions. He has also drawn short stories featuring Wonder Woman Harley Quinn and Mera. Currently he is drawing the ongoing series The Oddly Pedestrian Life of Christopher Chaos created by James Tynion.",
