    "id": "378918",
    "name": "Isabel Kim",
    "bio": "Isabel J. Kim lives near New York City in an apartment filled with books and swords. She is the author of numerous short stories and has won the Nebula, Locus, and the Shirley Jackson Award. Her work has been translated into multiple languages and reprinted in multiple best of the year anthologies. When she’s not writing, she’s practicing law or podcasting. Sublimation is her first novel.",
