    "name": "J.R. Ward",
    "bio": "J.R. Ward is the author of more than sixty novels, including those in her #1 New York Times bestselling Black Dagger Brotherhood series. There are more than twenty million copies of her novels in print worldwide, and they have been published in twenty-seven different countries. She lives in the south with her family.",
