    "id": "380707",
    "name": "Jacoby Salcedo",
    "bio": "Jacoby Salcedo is a comic book illustrator who is based in Olympia Washington. He is the artist of the DC Comics YA graphic novel THIS LAND IS OUR LAND: A BLUE BEETLE STORY with frequent collaborator Julio Anta. He is the co-creator of the Eisner nominated YA graphic novel FRONTERA with Anta. Jacoby is also the artist on Dark Horse mini-series IT'S ONLY TEENAGE WASTELAND with writer Curt Pires. Jacoby has been featured in multiple comic anthologies such as DC's Legion of Bloom Graphic Mundi's Covid Chronicles and the GLAAD award winning Young Men in Love.",
