    "name": "Jae Lee",
    "bio": "Jae Lee is a Korean-American comic book artist known for his dark style. He is an Eisner Award-winner for his work on Marvel's The Inhumans. During his time at Marvel Knights he co-created The Sentry with writer Paul Jenkins. Jae is currently drawing M1: Monster Racing League a new ongoing series for Image Comics.",
