    "id": "379192",
    "name": "Jason Rekulak",
    "bio": "Jason Rekulak lives in Philadelphia with his wife and family. His novels include Hidden Pictures (winner of a Goodreads Choice Award), The Last One at the Wedding (winner of the ITW Award for Best Standalone Thriller), and The Impossible Fortress (an Edgar Award finalist). His books have been translated into more than forty languages.",
