    "bio": "Jean Kwok is the New York Times and internationally bestselling author of The Leftover Woman, Searching for Sylvie Lee, Girl in Translation, Mambo in Chinatown, and her romantasy debut DOMINION, which came out from Putnam in July. Her work has been published in twenty countries and is taught in schools across the world. She lives in the New York area.\n\nFollow me on Threads\nFollow me on TikTok",
