    "id": "379425",
    "name": "Joe Rohde",
    "bio": "Disney Legend Joe Rohde spent 40 years with Walt Disney Imagineering, leading projects including Disney’s Animal Kingdom, Aulani, and Villages Nature near Disneyland Paris. Since retiring, he has consulted on projects for Virgin Galactic and the Jane Goodall Institute, while continuing to collaborate with Disney. An Explorers Club member, Rohde is also an artist whose expedition paintings reflect a lifelong passion for culture, nature, and exploration.",
