    "id": "378670",
    "name": "John Pearson",
    "altName": "John J. Pearson",
    "bio": "John J. Pearson is an Eisner Award–winning artist and illustrator based in Leeds, UK. He is the artist and co-creator of The Patron (with Christian Ward), The Smart Division (with Zack Kaplan) and In Bloom (with Michael Conrad). He has worked on Hellblazer: Dead in America and Batman: Urban Legends for DC Comics and The Department of Truth, Razorblades, The Infernals, and Blue in Green for Image Comics, as well as contributing to works published by Dark Horse, IDW, Heavy Metal, and BOOM! Studios among others.",
    "knownFor": "The Patron, The Smart Division, The Infernals, In Bloom",
