    "id": "380752",
    "name": "Jorge Fornes",
    "bio": "Jorge Fornés is a comic-book artist from Barcelona, he made his debut 12 years ago working on Detective comics(DC) and Thunderbolts(Marvel), in this time he has worked on titles as Wolverine, Dr.Strange, X-men, Guardians of Infinity, Avengers ,Magnus, Barbarella or Daredevil… Also he’s co-creator with writer Eliot Rahal of Aftershock’s miniseries “Hot lunch special”. He currently works for almost all companies, but mainly for DC Comics, where he has drawn series such as Rorschach, Danger Street, Batman, and Challengers of the Unknown, as well as multiple covers.",
