    "name": "Julio Anta",
    "bio": "Julio Anta is the writer of many graphic novels for young adults including the Eisner Award-nominated Frontera, the Bluebonnet Award-nominated Speak Up Santiago, This Land Is Our Land: A Blue Beetle Story, Sí, Se Puede: The Latino Heroes Who Changed the United States and Home at Image Comics. Julio was born and raised in Miami, Florida and currently resides in New York City.",
