    "id": "379863",
    "name": "Kate Rhodes",
    "bio": "Jen Xu and Kate Rhodes are a comic collaborative team who share the writing and illustrating of their books. Rhodes, a cartoonist, and Xu an animator, both graduated from the School of Visual Arts in New York City. They have a short comic in The Legend of Korra anthology and their long running webcomic Novae, was nominated for a Ringo award. Stories are their passion and they often spend their mornings discussing ideas over tea. They currently live together with their cuddly cats in Northern Colorado. Haven and the Fallen Giants is their first middle grade graphic novel.",
