    "id": "379590",
    "name": "Kevan Chandler",
    "bio": "Kevan Chandler grew up in the foothills of North Carolina with his parents and two siblings. The youngest of the bunch, he was the second to be diagnosed with Spinal Muscular Atrophy, a rare neuromuscular disease. He has a Bachelor's of Arts in Counseling from John Wesley College. An avid storyteller, Kevan is the author of several books and speaks worldwide about his unique life with a disability. He is also the founder of We Carry Kevan, a nonprofit striving to redefine accessibility as a cooperative effort.",
