    "id": "377613",
    "name": "Kirsty Rider",
    "bio": "Kirsty is best known for originating the role of Lune in Expedition 33, which earned her a Bafta nomination for Best Supporting Performer. She has performed at many of the world’s most prestigious theatres including; The National, The Almeida, The Globe, The Young Vic, The Royal Exchange and as Ophelia in Rob Icke’s Hamlet in New York. She also has an extensive TV career, starring as Alma Curran in Call The Midwife’s Christmas Special, Peacock (BBC), Such Brave Girls (Hulu), Industry (HBO).",
