    "bio": "Kristopher Triana is the Splatterpunk Award-winning author of Gone to See the River Man, Full Brutal, The Thirteenth Koyote, They All Died Screaming, and many other terrifying books. His work has been published in seven languages and has appeared in many anthologies and magazines, drawing praise from Rue Morgue Magazine, Cemetery Dance, Scream Magazine, and many more.\n\nHe lives in New England.",
