    "name": "Kwanza Osajyefo Johnson",
    "altName": "Kwanza Osajyefo",
    "bio": "Kwanza Osajyefo asks the question superhero comics kept avoiding: what if only Black people had superpowers? That question became BLACK crowdfunded hard optioned by Netflix and still surprising when strangers stop him at cons. He co-created the Humanoids' H1 line and co-wrote Ignited alongside Mark Waid built DC's Zuda webcomics platform from the ground up and spent years editing other people's stories at recently at BOOM! Studios and Archaia before returning the the trenches.",
