    "id": "379318",
    "name": "Leopoldo Goût",
    "bio": "Leopoldo Goût is a multidisciplinary artist, internationally published author, and Emmy-nominated producer. Born in Mexico City and trained at London’s renowned Central Saint Martins School of Art, Goût is known for blending memory, cultural legacy, and speculative visions of the future in his deeply personal and globally resonant works. His critically acclaimed novels include the Genius trilogy, Ghost Radio, Monarca, and Piñata, which was named one of Esquire’s Top 10 Horror Novels of 2023.",
