    "id": "378890",
    "name": "Lily Kim Qian",
    "bio": "Lily Kim Qian is a Chinese-Canadian artist based in New York. She graduated with a BFA in illustration from Parsons the New School of Design in 2021. Along with her illustration practice, she works as a Junior Designer at Penguin Young Readers. Until We Meet Again is her debut graphic novel with First Second books. In her spare time, she enjoys volunteering at shelters and hanging out with her very own cat assistant, Edgar.",
