    "bio": "Maddie Martinez is the USA Today bestselling author of The Maiden and Her Monster and the forthcoming novel The Haunting of Lady Death. She has a bachelor's in political science and a master's in international peace and conflict resolution, which greatly inspires her writing. Originally from Albuquerque, New Mexico, you can now find Maddie in New York City, filling her tiny apartment with an unwieldy number of books.",
