    "bio": "Madison Tyler Nelson has considered herself a writer since she received her first rejection letter at nine years old, and has been crafting dark, speculative stories ever since. While she (sadly) can’t see ghosts, Portrait of a Haunting was inspired by her childhood of growing up with incarcerated parents. She lives in New York with her husband and very loud Norwegian Elkhound.",
