    "id": "379423",
    "name": "Maggie Lovitt",
    "bio": "Maggie Lovitt is the Deputy News Editor at Collider, bringing half a decade of hands-on film and television experience to her entertainment reporting. She is a member of the Screen Actors Guild, Critics Choice Association, and National Press Club. Maggie's love for pop culture started early — attending her first Star Trek convention at just four years old. Now, she travels the world moderating panels from North America to Japan, celebrating all things nerdy.",
