    "altName": "Maria Wolf",
    "bio": "Indigenous Mexican-American Marvel cover artist Maria Wolf made her explosive Marvel debut on Voices: Women of Marvel #1 in 2021. Her distinct dangerously wild funky style quickly swept through blockbuster Marvel franchises such as various Spider-Man titles with her standouts including cover work for Voices: Comunidades #1 Doom Ghost Rider and all across the X-Men family of titles. \"\"",
