    "bio": "Marker Snyder is an illustrator, designer, and graphic artist currently based in Kingston, NY, where he lives in a rainbow house with his husband, two cats, and a very friendly turtle. Formerly a curator and exhibition designer in NYC, he now works primarily on developing illustrated projects for kids—from picture books through middle grade. Visit him online at www.drawingwithmarker.com.",
