    "id": "378500",
    "name": "Max Fiumara",
    "altName": "Max Fiumara with Splash Page Art",
    "bio": "Born in Argentina Max has worked in comics since 2002 for Avatar Press Marvel DC and Dark Horse. He's worked on everything from Amazing Spider-man Namor and Hulk smash Avengers to Lucifer and the zombie tale Black Gas with writer Warren Ellis. He's the co-creator of Four Eyes with his Spider-man writer Joe Kelly published Image comics. He's worked alongside Mike Mignola in B. P. R. D having shared art duties with his twin brother Sebastian on the ongoing series Abe Sapien. He worked with Jeff Lemire on the Black Hammer mini series Doctor Star DC's Lucifer series with his brother. He just wrapped up the Creator Owned series titled The Sacrificers with writer Rick Remender.",
