    "id": "378484",
    "name": "MICHAIL ALEXANDROS DIALYNAS",
    "altName": "Michael Dialynas",
    "bio": "Michael Dialynas is an Einser-nominated and GLAAD Media Award-winning comic artist and beast wrangler that resides in Athens Greece. He is the creator of ZAWA + The Belly of the Beast and the illustrator and co-creator of WYND and THE WOODS with James Tynion IV. Over the past few years he's been one of the main artists involved with IDW's TEENAGE MUTANT NINJA TURTLES series all the way up to the milestone issue 100. He has just finished the final WYND book with Tynion IV an exciting YA fantasy series from BOOM! Studios and building a new world for readers to enjoy this year more news to follow.",
