    "bio": "Oriana Leckert is the Head of Publishing at Kickstarter, where she helps creators bring a marvelous array of literary projects to life. She's written and edited for Vice, MTV News, Slate, Hyperallergic, Gothamist, Atlas Obscura, and many more. Her first book, Brooklyn Spaces: 50 Hubs of Culture and Creativity (Monacelli, 2015), grew out of a multi-year project chronicling the rise and fall of under-the-radar creative places across New York City. Follow her at @orianabklyn on most social platforms.",
