    "id": "379187",
    "name": "Pablo Cartaya",
    "bio": "PABLO CARTAYA is a New York Times best-selling and internationally acclaimed author as well as screenwriter, speaker, and educator. Pablo has collaborated with Disney, Apple TV+, and Sesame Street on projects adapted from film and television. His award-winning middle grade novels include: The Epic Fail of Arturo Zamora, Marcus Vega Doesn’t Speak Spanish, Each Tiny Spark, the climate dystopia The Last Beekeeper, the graphic novel Curveball, and most recently, A Hero’s Guide to Summer Vacation, recipient of the 2026 Pura Belpré Children’s Author Honor Book Award. He calls Miami home and Cuban American his cultura.",
