    "id": "378779",
    "name": "Paul Levitz",
    "bio": "Over a five decade career, Paul Levitz has been a comic fan (THE COMIC READER), editor (BATMAN), writer (LEGION OF SUPER-HEROES). executive (decades at DC Comics ending as President & Publisher), historian (MARVEL EXPLODES: FROM BULLPEN TO BIG BUSINESS), and educator (Columbia University, Pace University, NYU). He has been inducted into the Eisner Hall of Fame, and won numerous awards in the U.S. and Europe.",
