    "name": "Pepe Larraz",
    "bio": "Pepe Larraz is a Spanish comic book artist. In 2018 Pepe was selected as one of six artists for Marvel's Young Guns Program which spotlights the best emerging artists in the comics industry. He is best known for his revolutionary work on X-Men and the House of X miniseries. His work also includes The Avengers The Mighty Thor Wolverine Star Wars: Kanan. He is currently working on Amazing Spider-Man with writer Joe Kelly.",
