    "id": "380057",
    "name": "Raúl Allén",
    "bio": "Raúl Allén is an artist living in Valladolíd, Spain. Most recently, with PAtricia Martín, he illustrated the bestselling trilogy of Dune graphic novel adaptations for Abrams ComicArts, and has worked for Marvel Comics, Valiant, and DC Comics, with writers such as Matt Fraction, Jeff Lemire, Matt Kindt, and Peter Milligan.",
