    "id": "378523",
    "name": "Richard Ortiz",
    "altName": "Richard Ortiz with Splash Page Art",
    "bio": "Richard Ortiz is from Uruguay and has been working professionally as a comic artist since 2004. He has worked for DC Comics on Bombshells United DC Bombshells and the Wonder Woman '77 Special online series. He is most known for his cover art on Lady Death and other Coffin Comic titles over the years. He has also illustrated covers for numerous Zenescope titles. In recent years he has drawn covers for Archie Comics Valiant Comics including Bloodshot Special and All-New Harbinger #2 and for DC Comcis DC KO #1 Argentinian Exclusive Cover. He's also produced Record Album covers: Vor Faded Photographs and Always Maybe Tomorrow (3 different albums) by Yagya (Aðalsteinn Guðmundsson) and for Seeker by Carbon Based Lifeforms.",
