    "name": "Rodrigo Reis",
    "altName": "Rod Reis",
    "bio": "Rod Reis has been working in comics since the late 1990s building his foundation as a colorist on DC titles including Aquaman and Justice League. In 2015 he made the transition to full artist launching two creator-owned series at Image Comics: C. O. W. L. and Hadrian’s Wall. That shift opened the door to a run of high-profile Marvel work with interior art on Doctor Strange Winter Soldier and New Mutants. Now he is working at DC doing interiors for a six issue Supergirl Elseworlds",
