    "bio": "Eisner-winning artist Ronnie Vazquez is a queer Puerto Rican illustrator with experience in comics and visual development. With a range of storytelling experience from middle grade to young adult, their signature talent involves designing creatures of the toothy variety. They have illustrated for several independent anthologies and books and currently teach young artists in their community. When they're not drawing pictures or working with young artists, they can be found huddled in a blanket fort working on puzzles and eating fruit snacks.",
