    "id": "379137",
    "name": "Sarah Beth Durst",
    "bio": "Sarah Beth Durst is the New York Times bestselling author of over twenty-five books for adults, teens, and kids, including cozy fantasy The Spellshop. She's been awarded an American Library Association Alex Award, as well as a Mythopoeic Fantasy Award. Several of her books have been optioned for film/television, including Drink Slay Love, which was made into a TV movie and was a question on Jeopardy! She lives in Stony Brook, New York, with her husband, her children, and her ill-mannered cat.\n\nFollow me on BlueSky",
