    "id": "379581",
    "name": "Sofia Warren",
    "bio": "Sofia Warren has been a contributing cartoonist at The New Yorker since 2017. She is the author of the graphic memoir for adults Radical: My Year With a Socialist Senator, and her work has been published in MoMA Magazine, Catapult, Narrative Magazine, and the books Send Help! and Notes from the Bathroom Line. Film Nerds is her middle grade graphic novel debut.",
