    "id": "377584",
    "name": "Stephanie Phillips",
    "bio": "Stephanie Phillips is a bestselling comic book writer known for her work across DC, Marvel, and independent comics. She has written acclaimed runs on Harley Quinn, Batman, Phoenix, Wonder Woman, Grim, and Rogue Sun, earning a reputation for sharp character-driven storytelling and dynamic action. Phillips is also the creator of original series including Grim, We Only Kill Each Other, and Nuclear Power, making her one of the most prolific and versatile writers in comics today.",
