    "id": "379335",
    "name": "Stevie Van Zandt",
    "bio": "Stevie Van Zandt (Little Steven) is an award winning Musician, Performer, Songwriter, Arranger, Producer, Actor, Director, International DJ, Activist, Historian, Teacher, top ten NY Times bestseller list author, Radio Hall of Fame nominee, member of the New Jersey Hall of Fame and Rock and Roll Hall of Fame, and is recognized internationally as one of the world’s foremost authorities on both Contemporary and Traditional Rock and Roll.",
