    "bio": "#1 New York Times bestselling author Tessa Bailey has written over sixty romantic comedies, including It Happened One Summer and Fangirl Down. While spice and humor are her first love, she has been not-so-patiently waiting to visit the darker corners of her mind and finally indulged herself with Broken Rival. She lives on Long Island avoiding the sun and social interactions, then wonders why no one has called. She has no plans to change.",
