    "id": "378678",
    "name": "Tom Mason",
    "bio": "TOM MASON is an Emmy-winning television writer with credits as writer, story editor or head writer on more than 600 episodes of childrens’ entertainment. As a co-founder of Malibu Comics, he edited more than 1000 comics and wrote close to 100 of them. He was a founding editor of Bravura, the comic book imprint created by Howard Chaykin, Walter Simonson, Jim Starlin and others. He was also a co-founder of the super-hero universe, Ultraverse. He recently wrote a Lilo & Stitch graphic novel for TokyoPop, and has written more than 70 books for children.",
