    "id": "380054",
    "name": "Victoria Setian",
    "bio": "Victoria Setian started her career in Gotham City, specifically the third floor of DC Comics in the heart of New York City. Her writing chops eventually landed her a role on the DC interactive team, and since then she’s continued her crossover work with credits including the Batman: Arkham series, Mortal Kombat X, and Just Cause 4. She’s a game developer conference speaker and NYU Game Center Incubator advisor, and she helped pilot the Girl Scouts Game Design patch with Women in Games International. When she’s not tinkering on her next project, she’s hanging with her family or practicing Armenian folk dance.",
