    "id": "377565",
    "name": "Werther Dell'Edera",
    "bio": "Wether Dell'Edera is an Italian comic book artist. His collaborations with Publishers both in Italy and in the US over the years has given to him the chance to work on several projects with: IDW Dark Horse, Image, Sergio Bonelli Editore, Dynamite, Marvel, and DC. For BOOM! Studios, he is currently working with co-creator James Tynion IV on the awards winning series \"Something is Killing The Children\" and his spinoffs \"House of Slaughter” \"Book of Slaughter\" and \"Book of Butcher\" whilst most recently collaborating on an issue of Absolute Batman with Scott Snyder.",
