    "id": "380795",
    "name": "William Harms",
    "bio": "William Harms is the acclaimed writer of comic books and videogames. He is the writer and co-creator of the hit Image comic WHITE SKY and has also written for DC, Marvel, Top Cow, and others. His horror comic IMPALER was nominated for an International Horror Guild Award. He wrote the videogame inFAMOUS, which was released to wide acclaim, and led all writing on MAFIA III, for which he received a BAFTA nomination. MAFIA III was called a \"cultural milestone\" by the Washington Post. His horror-western, SON OF PERDITION, received positive reviews from Kirkus and Publisher's Weekly. He currently lives in Southern California.",
    "knownFor": "White Sky",
