    "name": "Ytasha L. Womack",
    "bio": "Ytasha L. Womack is a writer, cultural critic, and filmmaker recognized for her work in Afrofuturism, race, and speculative fiction. She is the author of Afrofuturism: The World of Black Sci Fi & Fantasy Culture (2013), Black Panther: A Cultural Exploration (2023), The Afrofuturist Evolution: Creative Paths to Self Discovery (2025), and the forthcoming graphic novel Black Moon Ritual.",
