    "name": "Zack Kaplan",
    "bio": "Zack Kaplan is the comic creator of many comic series and graphic novels including a slate of comics at Dark Horse such as ONLY THE SAVAGE ARE LEFT THE SMART DIVISION KILL ALL IMMORTALS MASTERMINDS and THE MIDNIGHT: SHADOWS as well as notable titles PORT OF EARTH and ECLIPSE. After just a few short years he has worked with publishers such as Image/Top Cow Dark Horse Aftershock Vault Mad Cave Scout Comics and DC Comics. He has optioned several of his titles for FILM/TV adaptation and he has also collaborated with brands like Oakley in narrative design brand storytelling and animation video writing. He teaches Writing for Comics and Graphic Novels at Loyola Marymount University. He currently lives in Los Angeles.",
